 static T Bind<T>(IntPtr dll,string name)where T:class{var p=GetProcAddress(dll,name);if(p==IntPtr.Zero)throw new InvalidOperationException("Required SDK export unavailable");return Marshal.GetDelegateForFunctionPointer(p,typeof(T))as T;}
 static IntPtr At(IntPtr dll,int rva){return new IntPtr(dll.ToInt64()+rva);}
 static T Private<T>(IntPtr dll,int rva)where T:class{return Marshal.GetDelegateForFunctionPointer(At(dll,rva),typeof(T))as T;}
 static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 static int Offset(byte[] b,int rva){int pe=BitConverter.ToInt32(b,60),count=BitConverter.ToUInt16(b,pe+6),table=pe+24+BitConverter.ToUInt16(b,pe+20);for(int i=0;i<count;i++){int p=table+i*40,start=BitConverter.ToInt32(b,p+12),size=BitConverter.ToInt32(b,p+16);if(rva>=start&&rva<start+size)return BitConverter.ToInt32(b,p+20)+rva-start;}throw new InvalidDataException("Private entry outside image sections");}
 static void Verify(string file){var b=File.ReadAllBytes(file);if(Hash(b)!=SdkHash)throw new InvalidDataException("Unsupported SDK fingerprint; no device opened");foreach(var item in new[]{new{rva=0x3f6dd0,hex="5557565389cb83ec2c807c244c008b6c"},new{rva=0x3f23c0,hex="5557565389cb83ec2c8b81680900008b"},new{rva=0x3f3120,hex="5557565389ce83ec2c8b81680900008b"}}){int offset=Offset(b,item.rva);var actual=BitConverter.ToString(b,offset,16).Replace("-","").ToLowerInvariant();if(actual!=item.hex)throw new InvalidDataException("Private entry signature mismatch");}}
 static string Prepare(){string local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),folder=Path.Combine(local,"LifeAC-Lighting","vendor"),trial=Path.Combine(local,"LifeAC-DMX-Trial","vendor-2023");Directory.CreateDirectory(folder);foreach(var item in new[]{new{name="DevKit.dll",hash=SdkHash},new{name="libusb0.dll",hash=UsbHash}}){string dest=Path.Combine(folder,item.name);if(!File.Exists(dest)||Hash(File.ReadAllBytes(dest))!=item.hash){string old=Path.Combine(trial,item.name);if(!File.Exists(old)||Hash(File.ReadAllBytes(old))!=item.hash)throw new InvalidOperationException("The verified USB runtime is missing. Use Lighting's connection setup first.");File.Copy(old,dest,true);}}Verify(Path.Combine(folder,"DevKit.dll"));return folder;}

 static int Be16(byte[] b,int i){if(i<0||i+1>=b.Length)throw new InvalidDataException("Truncated standalone field");return b[i]*256+b[i+1];}
 static byte[] Packet(IntPtr core,IntPtr device,ReadCommand read,int command,int scene,int universe,int step){
  if(command!=0x21&&command!=0x51&&command!=0x61&&command!=0x71)throw new InvalidOperationException("Command is not in the read-only allowlist");
  var header=new byte[26];Array.Copy(new byte[]{0x55,0xaa,0x55,0x11,0,0x55,0xaa,0xff},header,8);byte sequence=unchecked((byte)(Marshal.ReadByte(core,0x8e2)+1));Marshal.WriteByte(core,0x8e2,sequence);header[10]=sequence;header[12]=(byte)universe;header[13]=0x10;header[14]=0x50;header[16]=(byte)(scene>>8);header[17]=(byte)scene;header[20]=(byte)command;header[21]=(byte)scene;header[22]=(byte)(step>>8);header[23]=(byte)step;Marshal.Copy(header,0,IntPtr.Add(core,0x970),26);
  if(!read(core,device,command,0x50,0))throw new InvalidOperationException("Standalone read rejected: command "+command.ToString("X2")+", scene "+scene+", output "+universe+", step "+step);
  Marshal.Copy(IntPtr.Add(core,0x11a4),header,0,26);if(!header.Take(8).SequenceEqual(new byte[]{0x55,0xaa,0x55,0x11,0,0x55,0xaa,0xff})||header[10]!=sequence||header[13]!=0x11||header[14]!=0x51||header[20]!=command)throw new InvalidDataException("Standalone response identity mismatch");int count=header[8]|header[9]<<8;if(count<1||count>1028)throw new InvalidDataException("Standalone response length outside bounds");var payload=new byte[count];Marshal.Copy(IntPtr.Add(core,0x11be),payload,0,count);return payload;
 }
 static byte[] Repeat(IntPtr core,IntPtr device,ReadCommand read,int command,int scene,int universe,int step,int length){var first=Packet(core,device,read,command,scene,universe,step);var second=Packet(core,device,read,command,scene,universe,step);if(first.Length<length||second.Length<length||!first.Take(length).SequenceEqual(second.Take(length)))throw new InvalidDataException("Repeated scene read did not match: command "+command.ToString("X2")+", scene "+scene+", step "+step);return first;}
 static void Inventory(Dictionary<string,object> report,IntPtr core,IntPtr device,ReadCommand read,byte[] configuration){
  int model=Marshal.ReadInt32(device,8);report["sdkLayoutModel"]=model;report["sdkProductCode"]=Marshal.ReadInt32(device,4);report["sdkReportedUniverses"]=Marshal.ReadInt32(device,0x38);report["sceneReadProtocol"]="Legacy 0x50/0x51 header, 0x61 triggers, 0x71 steps";
  if(!new[]{6,7,9,10,13}.Contains(model))throw new InvalidOperationException("Configuration read succeeded. Scene decoder requires verification for layout model "+model+"; no guessed scene commands were sent");
  int channelA=Be16(configuration,0),channelB=Be16(configuration,2),count=Be16(configuration,4);if(channelA<0||channelA>512||channelB<0||channelB>512||channelA+channelB<1||count<0||count>512)throw new InvalidDataException("Standalone configuration channel/scene counts are out of range");report["storedSceneCount"]=count;report["storedChannels"]=new[]{channelA,channelB};var scenes=new List<object>();report["scenes"]=scenes;int frames=0;var clock=Stopwatch.StartNew();
  for(int id=1;id<=count;id++){
   if(clock.ElapsedMilliseconds>540000)throw new InvalidOperationException("Read stopped at its nine-minute limit; partial inventory retained");Console.Error.WriteLine("Reading scene "+id+" / "+count);Console.Error.Flush();var header=Repeat(core,device,read,0x51,id,0,0,model==6||model==7?18:50);if(header.Length<18||Be16(header,0)!=id)throw new InvalidDataException("Stored scene header did not match the requested scene index");int steps=Be16(header,2);if(steps>8192)throw new InvalidDataException("Stored step count is outside the supported read limit");var triggers=Repeat(core,device,read,0x61,id,0,0,model==6||model==7?15:17);var scene=new Dictionary<string,object>{{"index",id},{"stepCount",steps},{"headerBase64",Convert.ToBase64String(header)},{"triggersBase64",Convert.ToBase64String(triggers)},{"headerKnownBytes",model==6||model==7?18:50}};var values=new List<object>();scene["steps"]=values;scenes.Add(scene);
   for(int step=0;step<steps;step++){
    if(++frames>32768||clock.ElapsedMilliseconds>540000)throw new InvalidOperationException("Read limit reached; partial inventory retained");var outputs=new List<object>();for(int u=1;u<=2;u++){int channels=u==1?channelA:channelB;if(channels==0)continue;var bytes=Repeat(core,device,read,0x71,id,u,step,channels+4);if(bytes.Length<channels+4)throw new InvalidDataException("Stored DMX step was shorter than its configured channel count");outputs.Add(new{universe=u,fadeTicks=Be16(bytes,0),holdTicks=Be16(bytes,2),fadeMs=Be16(bytes,0)*40,holdMs=Be16(bytes,2)*40,valuesBase64=Convert.ToBase64String(bytes,4,channels),replyBase64=Convert.ToBase64String(bytes)});}values.Add(new{index=step,outputs=outputs});
   }
  }
  var after=Packet(core,device,read,0x21,0,0,0);int configLength=model==6||model==7?19:model==13?31:24;if(configuration.Length<configLength||after.Length<configLength||!configuration.Take(configLength).SequenceEqual(after.Take(configLength)))throw new InvalidDataException("Controller configuration changed during the read; backup is not marked complete");report["completeSceneRead"]=true;report["repeatReadVerified"]=true;report["completeMemoryBackup"]=false;report["backupScope"]="All configured scene headers, triggers and used DMX channels/steps. Additional device-wide tables and allocator state are not yet backed up; not yet a proven restoration image.";report["interpretation"]="Scene data read directly from controller. Fixture identities cannot be discovered from ordinary DMX. Names and fixture patch remain separate PC show data.";
 }
 // Exercises packet construction and inventory failure paths in allocated memory.
 // This mode never loads the SDK, enumerates USB, or opens any device.
 static int SelfTest(){
  IntPtr core=Marshal.AllocHGlobal(0x2000),device=Marshal.AllocHGlobal(64);int calls=0;string fault="";
  try{Marshal.Copy(new byte[0x2000],0,core,0x2000);Marshal.Copy(new byte[64],0,device,64);Marshal.WriteInt32(device,8,6);var config=new byte[128];config[0]=1;config[1]=64;config[5]=2;
   ReadCommand fake=delegate(IntPtr c,IntPtr d,int command,int group,int initialise){
    calls++;var h=new byte[26];Marshal.Copy(IntPtr.Add(c,0x970),h,0,26);int scene=Be16(h,16),step=Be16(h,22);if(group!=0x50||initialise!=0||h[13]!=0x10||h[14]!=0x50||h[20]!=command||h[21]!=(byte)scene)throw new Exception("Incorrect read request");byte[] payload;
    if(command==0x21){payload=(byte[])config.Clone();if(fault=="changed")payload[5]=3;}
    else if(command==0x51){payload=new byte[128];payload[1]=(byte)(fault=="scene"?scene+1:scene);payload[3]=2;}
    else if(command==0x61)payload=new byte[128];
    else if(command==0x71){if(h[12]!=1||scene<1||scene>2||step>1)throw new Exception("Incorrect step address");payload=new byte[fault=="short"?5:324];payload[1]=25;payload[3]=50;for(int i=4;i<payload.Length;i++)payload[i]=(byte)(i+scene+step);}
    else throw new Exception("Unexpected command");if(fault=="unstable"&&command==0x71)payload[4]=(byte)calls;
    h[8]=(byte)payload.Length;h[9]=(byte)(payload.Length>>8);h[13]=0x11;h[14]=0x51;if(fault=="sequence")h[10]++;Marshal.Copy(h,0,IntPtr.Add(c,0x11a4),26);Marshal.Copy(payload,0,IntPtr.Add(c,0x11be),payload.Length);return true;
   };
   var good=new Dictionary<string,object>();Inventory(good,core,device,fake,config);if(!(bool)good["completeSceneRead"]||(bool)good["completeMemoryBackup"]||((List<object>)good["scenes"]).Count!=2||calls!=17)throw new Exception("Inventory result mismatch");
   foreach(string kind in new[]{"scene","short","changed","sequence","unstable"}){fault=kind;bool rejected=false;try{Inventory(new Dictionary<string,object>(),core,device,fake,config);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Accepted invalid response: "+kind);}
   int before=calls;try{Packet(core,device,fake,0x70,1,1,0);throw new Exception("Write command accepted");}catch(InvalidOperationException){}if(calls!=before)throw new Exception("Disallowed command reached transport");Console.WriteLine("PASS: scene inventory, step addressing, changed configuration, wrong scene, short payload, wrong sequence, write-command rejection; no SDK or USB access.");return 0;
  }finally{Marshal.FreeHGlobal(core);Marshal.FreeHGlobal(device);}
 }
 static int Main(string[] args){var elapsed=Stopwatch.StartNew();if(args.Length==1&&args[0]=="--self-test")return SelfTest();var report=new Dictionary<string,object>{{"schema",1},{"tool","LifeAC standalone scene reader 0.3"},{"at",DateTime.UtcNow.ToString("o")},{"experimental",true},{"completeMemoryBackup",false},{"memoryWritesEnabled",false},{"dmxFramesSent",0},{"sdkSha256",SdkHash},{"expectedUsb",new{vid="0483",pid="A1DF"}},{"operation","Read configuration and configured scenes using traced ProDMX legacy read commands"}};IntPtr self=IntPtr.Zero;Close close=null;
 try{
  if(args.Length==2&&args[0]=="--verify-only"){Verify(args[1]);Console.WriteLine("Verified fingerprint and all three private entry signatures without loading the DLL or accessing USB.");return 0;}
  if(IntPtr.Size!=4)throw new PlatformNotSupportedException("The probe must run as x86");foreach(string process in new[]{"Pro2","ProDMX","LifeAC Lighting","LifeAC-Diagnostics","LifeAC-Sample"})if(Process.GetProcessesByName(process).Length>0)throw new InvalidOperationException("Close Lighting, ProDMX and previous lighting tools before reading.");
  string folder=Prepare();IntPtr dll=LoadLibraryEx(Path.Combine(folder,"DevKit.dll"),IntPtr.Zero,0x100|0x800);if(dll==IntPtr.Zero)throw new InvalidOperationException("USB runtime could not load");
  self=Bind<Factory>(dll,"createDevKitClass")();if(self==IntPtr.Zero)throw new InvalidOperationException("SDK factory failed");close=Bind<Close>(dll,"_ZN6DevKit15closeAllDevicesEv");
  int count=Bind<Count>(dll,"_ZN6DevKit21getNumberOfUsbDevicesEv")(self);report["interfaceCount"]=count;if(count!=1)throw new InvalidOperationException("Expected one USB interface; found "+count);
  // NoDmx=0 is declared in the supplied SDK header. No initDevices or live-frame
  // method is called. Maintenance access may pause standalone playback.
  if(!Bind<Open>(dll,"_ZN6DevKit13openUsbDeviceEi13cqInOutConfigPhi")(self,0,0,IntPtr.Zero,0))throw new InvalidOperationException("Maintenance connection rejected");report["maintenanceOpened"]=true;
  IntPtr fw=Marshal.AllocHGlobal(4);try{Marshal.Copy(new byte[4],0,fw,4);if(!Bind<Firmware>(dll,"_ZN6DevKit19readFirmwareVersionEiR17cqFirmwareVersion")(self,0,fw))throw new InvalidOperationException("Firmware read rejected");var version=new byte[4];Marshal.Copy(fw,version,0,4);report["firmware"]=String.Join(".",version.Select(x=>x.ToString()).ToArray());if(!version.SequenceEqual(new byte[]{2,4,2,3}))throw new InvalidOperationException("Unexpected firmware; experimental configuration read was not attempted");}finally{Marshal.FreeHGlobal(fw);}
  IntPtr list=Marshal.ReadIntPtr(At(dll,0xd8bba0));if(list==IntPtr.Zero)throw new InvalidOperationException("Device list missing");int first=Marshal.ReadInt32(list,8),last=Marshal.ReadInt32(list,12);if(first<0||first>1024||last-first!=1)throw new InvalidOperationException("Unexpected device list layout");IntPtr device=Marshal.ReadIntPtr(list,16+first*4);if(device==IntPtr.Zero)throw new InvalidOperationException("Device handle missing");
  IntPtr core=At(dll,0xd8b240),flag=At(dll,0xd8af24);var pause=Private<Pause>(dll,0x3f23c0);var resume=Private<Pause>(dll,0x3f3120);var read=Private<ReadCommand>(dll,0x3f6dd0);bool paused=false;
  try{Marshal.WriteByte(flag,1);pause(core,IntPtr.Zero);paused=true;if(!read(core,device,0x21,0x50,1))throw new InvalidOperationException("The controller rejected the standalone configuration read; no fallback or write was attempted");
   var header=new byte[26];Marshal.Copy(IntPtr.Add(core,0x11a4),header,0,header.Length);if(!header.Take(8).SequenceEqual(new byte[]{0x55,0xaa,0x55,0x11,0,0x55,0xaa,0xff})||header[13]!=0x11||header[14]!=0x51||header[20]!=0x21)throw new InvalidDataException("Standalone response did not match the expected legacy read reply");int length=header[8]|header[9]<<8;if(length<1||length>512)throw new InvalidDataException("Unexpected standalone reply length; configuration bytes were not exported");var payload=new byte[length];Marshal.Copy(IntPtr.Add(core,0x11be),payload,0,length);report["configurationReadAccepted"]=true;report["configurationBytes"]=length;report["configurationBase64"]=Convert.ToBase64String(payload);report["configurationSha256"]=Hash(payload);report["interpretation"]="Configuration read succeeded; gathering scene headers, triggers and steps.";Inventory(report,core,device,read,payload);
  }finally{if(paused)resume(core,IntPtr.Zero);Marshal.WriteByte(flag,0);}
  report["ok"]=true;
 }catch(Exception error){report["ok"]=false;report["error"]=error is InvalidOperationException||error is InvalidDataException?error.Message:error.GetType().Name;}
 finally{report["elapsedMs"]=elapsed.ElapsedMilliseconds;if(close!=null&&self!=IntPtr.Zero)try{close(self);report["interfaceClosed"]=true;}catch{report["interfaceClosed"]=false;}Console.WriteLine(Json.Serialize(report));}
 return report.ContainsKey("ok")&&(bool)report["ok"]?0:1;
 }
